const migrationId = crypto.randomUUID();
return [{
  json: {
    migration_id: migrationId,
    started_at: new Date().toISOString(),
    batch_size: 1000,
    scope: {
      postgres: "all tables in schema pro + explicit public aliases used by legacy workflows",
      n8n_datatables: ["nitro_stock"],
    },
  },
}];

const BATCH_SIZE = Number($('Create migration context').first().json.batch_size || 1000);
const migrationId = String($('Create migration context').first().json.migration_id);
const rows = $input.all();
const groups = new Map();

function objectOrThrow(value, label) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value === 'string') {
    const parsed = JSON.parse(value);
    if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed;
  }
  throw new Error(`Invalid row_data for ${label}`);
}

for (const item of rows) {
  const row = item.json || {};
  const sourceSystem = String(row.source_system || 'n8n_postgres_pro');
  const sourceSchema = String(row.source_schema || 'pro');
  const sourceTable = String(row.source_table || 'unknown');
  const key = `${sourceSystem}|${sourceSchema}|${sourceTable}`;
  const sourceCount = Number(row.source_count || 0);

  if (!groups.has(key)) {
    groups.set(key, {
      sourceSystem,
      sourceSchema,
      sourceTable,
      sourceCount,
      items: [],
    });
  }

  const group = groups.get(key);
  if (group.sourceCount !== sourceCount) {
    throw new Error(`Inconsistent source_count for ${key}: ${group.sourceCount} vs ${sourceCount}`);
  }

  if (row.is_empty === true || row.row_data == null) continue;

  const rowData = objectOrThrow(row.row_data, key);
  const externalId = String(row.external_id || '').trim();
  if (!externalId) throw new Error(`Missing external_id for ${key}`);

  group.items.push({ external_id: externalId, row_data: rowData });
}

const output = [];
for (const group of groups.values()) {
  if (group.items.length !== group.sourceCount) {
    throw new Error(
      `Source extraction mismatch for ${group.sourceSchema}.${group.sourceTable}: ` +
      `expected ${group.sourceCount}, got ${group.items.length}`
    );
  }

  const totalBatches = Math.max(1, Math.ceil(group.items.length / BATCH_SIZE));
  for (let batchIndex = 0; batchIndex < totalBatches; batchIndex++) {
    const offset = batchIndex * BATCH_SIZE;
    const batch = group.items.slice(offset, offset + BATCH_SIZE);
    const requestId = crypto.randomUUID();
    const idempotencyKey = [
      'broki-legacy-v3', migrationId, group.sourceSystem,
      group.sourceSchema, group.sourceTable, String(batchIndex)
    ].join(':');

    output.push({
      json: {
        auth: {
          request_id: requestId,
          timestamp: Math.floor(Date.now() / 1000).toString(),
          idempotency_key: idempotencyKey,
        },
        body: {
          migration_id: migrationId,
          source_system: group.sourceSystem,
          source_schema: group.sourceSchema,
          source_table: group.sourceTable,
          batch_index: batchIndex,
          total_batches: totalBatches,
          total_rows: group.sourceCount,
          items: batch,
        },
      },
    });
  }
}

if (output.length === 0) throw new Error('No PostgreSQL Broki tables were discovered');
return output;

const BATCH_SIZE = Number($('Create migration context').first().json.batch_size || 1000);
const migrationId = String($('Create migration context').first().json.migration_id);
const sourceSystem = 'n8n_datatable';
const sourceSchema = 'n8n';
const sourceTable = 'nitro_stock';
const rawRows = $input.all().map((item) => item.json || {});

function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
  return '{' + Object.keys(value).sort().map((k) => JSON.stringify(k) + ':' + stableStringify(value[k])).join(',') + '}';
}

const indexed = rawRows.map((row, index) => {
  const base = String(
    row.external_id ?? row.id ?? row.uuid ?? row.ubicacion ?? row.location ?? `nitro-row-${index + 1}`
  ).trim();
  return { row, index, base, contentKey: stableStringify(row) };
});

const groups = new Map();
for (const entry of indexed) {
  if (!groups.has(entry.base)) groups.set(entry.base, []);
  groups.get(entry.base).push(entry);
}

const items = new Array(indexed.length);
for (const [base, group] of groups) {
  if (group.length === 1) {
    items[group[0].index] = { external_id: base, row_data: group[0].row };
    continue;
  }
  group.sort((a, b) => a.contentKey.localeCompare(b.contentKey) || a.index - b.index);
  group.forEach((entry, dupIndex) => {
    items[entry.index] = {
      external_id: `${base}#dup:${dupIndex + 1}`,
      row_data: entry.row,
    };
  });
}

const totalBatches = Math.max(1, Math.ceil(items.length / BATCH_SIZE));
const output = [];
for (let batchIndex = 0; batchIndex < totalBatches; batchIndex++) {
  const batch = items.slice(batchIndex * BATCH_SIZE, (batchIndex + 1) * BATCH_SIZE);
  output.push({
    json: {
      auth: {
        request_id: crypto.randomUUID(),
        timestamp: Math.floor(Date.now() / 1000).toString(),
        idempotency_key: [
          'broki-legacy-v3', migrationId, sourceSystem, sourceSchema, sourceTable, String(batchIndex)
        ].join(':'),
      },
      body: {
        migration_id: migrationId,
        source_system: sourceSystem,
        source_schema: sourceSchema,
        source_table: sourceTable,
        batch_index: batchIndex,
        total_batches: totalBatches,
        total_rows: items.length,
        items: batch,
      },
    },
  });
}
return output;

const item = $json;
const statusCode = item.statusCode ?? item.status ?? 200;
const response = item.body ?? item;
if (statusCode < 200 || statusCode >= 300) {
  throw new Error(`Import HTTP ${statusCode}: ${JSON.stringify(response).slice(0, 1000)}`);
}
if (!response || response.ok !== true) {
  throw new Error(`Import request failed: ${JSON.stringify(response).slice(0, 1000)}`);
}
if (Number(response.received) !== Number(response.upserted)) {
  throw new Error(
    `Partial import ${response.source_schema}.${response.source_table} batch ${response.batch_index}: ` +
    `received=${response.received}, upserted=${response.upserted}`
  );
}
if (Array.isArray(response.errors) && response.errors.length > 0) {
  throw new Error(`Import errors: ${JSON.stringify(response.errors).slice(0, 1500)}`);
}
if (response.snapshot_status === 'partial' || response.snapshot_status === 'failed') {
  throw new Error(
    `Snapshot ${response.snapshot_status} for ${response.source_schema}.${response.source_table} batch ${response.batch_index}`
  );
}
return { json: response };

const responses = $input.all().map((item) => item.json || {});
if (!responses.length) throw new Error('No import responses received');
const migrationIds = [...new Set(responses.map((r) => String(r.migration_id || '')))].filter(Boolean);
if (migrationIds.length !== 1) throw new Error(`Unexpected migration ids: ${migrationIds.join(', ')}`);

const groups = new Map();
for (const r of responses) {
  const key = `${r.source_system}|${r.source_schema || ''}|${r.source_table}`;
  if (!groups.has(key)) {
    groups.set(key, {
      source_system: r.source_system,
      source_schema: r.source_schema || null,
      source_table: r.source_table,
      expected_rows: Number(r.total_rows || 0),
      batchUpserts: new Map(),
      failed_rows: 0,
      batches_seen: new Set(),
      total_batches: Number(r.total_batches || 1),
      snapshot_status: r.snapshot_status || 'running',
    });
  }
  const g = groups.get(key);
  if (g.expected_rows !== Number(r.total_rows || 0)) throw new Error(`total_rows drift for ${key}`);
  const batchIndex = Number(r.batch_index || 0);
  g.batchUpserts.set(batchIndex, Number(r.upserted || 0));
  g.batches_seen.add(batchIndex);
  if (Array.isArray(r.errors) && r.errors.length > 0 && !r.replay) {
    g.failed_rows += r.errors.length;
  }
  if (r.snapshot_status) g.snapshot_status = r.snapshot_status;
}

const manifest = [];
const import_summary = [];
for (const [key, g] of groups) {
  const imported_rows = [...g.batchUpserts.values()].reduce((a, b) => a + b, 0);
  if (g.batches_seen.size !== g.total_batches) {
    throw new Error(`Missing batches for ${key}: ${g.batches_seen.size}/${g.total_batches}`);
  }
  for (let i = 0; i < g.total_batches; i++) {
    if (!g.batches_seen.has(i)) throw new Error(`Missing batch index ${i} for ${key}`);
  }
  if (imported_rows !== g.expected_rows || g.failed_rows !== 0) {
    throw new Error(
      `Import count mismatch for ${key}: expected=${g.expected_rows}, imported=${imported_rows}, failed=${g.failed_rows}`
    );
  }
  if (g.snapshot_status !== 'success') {
    throw new Error(`Snapshot not success for ${key}: ${g.snapshot_status}`);
  }
  manifest.push({
    source_system: g.source_system,
    source_schema: g.source_schema,
    source_table: g.source_table,
    expected_rows: g.expected_rows,
  });
  import_summary.push({
    ...manifest[manifest.length - 1],
    imported_rows,
    total_batches: g.total_batches,
    snapshot_status: g.snapshot_status,
  });
}

manifest.sort((a, b) => `${a.source_system}.${a.source_table}`.localeCompare(`${b.source_system}.${b.source_table}`));
return [{
  json: {
    ok: true,
    migration_id: migrationIds[0],
    imported_tables: manifest.length,
    imported_rows: manifest.reduce((sum, row) => sum + row.expected_rows, 0),
    manifest,
    import_summary,
  },
}];

