={{ (() => {
  const agg = $('Aggregate import results').first()?.json;
  const ctx = $('Create migration context').first()?.json;
  const migrationId = agg?.migration_id || ctx?.migration_id;
  const manifest = agg?.manifest;
  if (!migrationId) {
    throw new Error(
      'Audit source manifest: missing migration_id. Re-run the FULL workflow from Manual Trigger (do not retry only this node).'
    );
  }
  if (!Array.isArray(manifest)) {
    throw new Error(
      'Audit source manifest: missing manifest from Aggregate import results. Re-run FULL workflow from Manual Trigger.'
    );
  }
  return JSON.stringify({ p_manifest: manifest, p_migration_id: String(migrationId) });
})() }}

