function body(name) {
  const data = $(name).first().json;
  return data.body ?? data;
}
const sourceAudit = body('Audit source manifest');
const snapshotAudit = body('Audit migration snapshots');
const entityAudit = body('Audit canonical entity counts');
const rawParity = body('Audit raw payload parity');

const sourceFailures = (Array.isArray(sourceAudit) ? sourceAudit : []).filter((r) => r.status !== 'OK');
const snapshotFailures = (Array.isArray(snapshotAudit) ? snapshotAudit : []).filter(
  (r) => r.status !== 'success' || Number(r.delta || 0) !== 0 || Number(r.failed_rows || 0) !== 0
);
const entityFailures = (Array.isArray(entityAudit) ? entityAudit : []).filter(
  (r) => !['OK', 'EMPTY', 'RAW_ONLY'].includes(r.status)
);
const rawDrifts = Array.isArray(rawParity) ? rawParity : [];

if (sourceFailures.length || snapshotFailures.length || entityFailures.length || rawDrifts.length) {
  throw new Error(JSON.stringify({
    message: 'BROKI migration parity failed',
    sourceFailures,
    snapshotFailures,
    entityFailures,
    rawDrifts: rawDrifts.slice(0, 50),
  }));
}

return [{ json: { ok: true } }];
